{
  "assessment": "The source provides two temperature branches (T=10^-6 and T=1) for the incompressible kinetic energy E_i versus quench time tau_Q, with fitted power laws and explicit parameter values. The selected cluster is the incompressible kinetic energy scaling at equilibration time, which is supported by the main text and End Matter. The source reports fitted exponents and amplitudes for both branches, and the reviewer figure evidence confirms the applicability interval [100,1000] for both branches. The case is authoring-ready with one control (tau_Q), one readout (E_i), and two claims (one per temperature branch).",
  "case_authoring_ready": true,
  "source": {
    "citation": "Seong-Ho Shinn, Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
    "journal_doi": "10.1103/b16v-hwp2",
    "arxiv_versioned_id": "2506.21670v3"
  },
  "paper_scope": "The paper studies spontaneous quantum turbulence (SQT) in a 2D Bose-Einstein condensate formed by a thermal quench, using stochastic projected Gross-Pitaevskii simulations. It establishes Kibble-Zurek scaling of vortex number and equilibration time, Kolmogorov scaling of the incompressible kinetic energy spectrum, and universal collapse of spectra under KZ rescaling. The selected cluster focuses on the incompressible kinetic energy E_i at equilibration time as a function of quench duration tau_Q, with two temperature branches (T=10^-6 and T=1).",
  "mechanisms": [
    {
      "mechanism_id": "KZ_scaling_Ei",
      "statement": "The incompressible kinetic energy E_i at equilibration time scales with quench duration as E_i proportional to tau_Q^{-(1+2 nu)/(1+z nu)}, with mean-field exponents nu=1/2 and z=2 giving E_i proportional to tau_Q^{-1}. This follows from approximating E_i as a sum of isolated vortex contributions, each scaling with the KZ correlation length and background density.",
      "equations": [
        "E_i \\propto \\tau_Q^{-(1+2\\nu)/(1+z\\nu)}",
        "E_i \\simeq (1/2) n_v \\int_{D_{\\hat{\\xi}}} |u_v(r)|^2 d^2r",
        "\\int_{D_{\\hat{\\xi}}} |u_v(r)|^2 d^2r \\simeq 2\\pi \\rho \\ln(\\hat{\\xi}/r_v)"
      ],
      "variable_names": [
        "E_i",
        "tau_Q",
        "nu",
        "z",
        "n_v",
        "rho",
        "hat_xi",
        "r_v"
      ],
      "parameters": [
        {
          "name": "nu_critical_exponent",
          "value": 0.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "correlation-length critical exponent",
          "anchors": [
            {
              "line_start": 167,
              "line_end": 167,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        },
        {
          "name": "z_dynamic_exponent",
          "value": 2,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "dynamic critical exponent",
          "anchors": [
            {
              "line_start": 167,
              "line_end": 167,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 414,
          "line_end": 417,
          "support": "Equation (eq:scaling_E_i_nu_z) states E_i proportional to tau_Q^{-(1+2 nu)/(1+z nu)}."
        },
        {
          "line_start": 418,
          "line_end": 442,
          "support": "Derivation: E_i approximated as sum over n_v vortex contributions, with single-vortex integral yielding 2 pi rho ln(hat_xi/r_v), subleading logarithmic correction."
        },
        {
          "line_start": 443,
          "line_end": 444,
          "support": "Fitted power laws for two temperatures confirm predicted tau_Q^{-1} behavior based on mean-field exponents nu=1/2 and z=2."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "simulation_parameters",
      "statement": "Periodic homogeneous 2D box of size L=30, relaxation time t_r=10, initial chemical potential mu_i=0.1, final chemical potential mu_f=20, coupling g=1, damping gamma=0.03, energy cutoff epsilon_cut=2.5 mu_f. The system is initialized with Psi_C=0 and relaxed for t_r before the quench.",
      "anchors": [
        {
          "line_start": 505,
          "line_end": 507,
          "support": "Table of simulation parameters: L=30, t_r=10, mu_i=0.1, mu_f=20, g=1, gamma=0.03, T=1, epsilon_cut=2.5 mu_f."
        },
        {
          "line_start": 491,
          "line_end": 491,
          "support": "Simulations performed in a periodic L x L homogeneous box with V(r)=0, Psi_C=0 initial condition, relaxed for t_r time units before quench."
        }
      ]
    },
    {
      "condition_id": "temperature_T_low",
      "statement": "Temperature T = 10^-6 (in dimensionless units), corresponding to O(10^-6) nK physically. Used for the low-temperature branch of the E_i scaling.",
      "anchors": [
        {
          "line_start": 390,
          "line_end": 390,
          "support": "Panel (a) shows E_i at equilibration for various tau_Q at temperature T = 10^-6."
        },
        {
          "line_start": 671,
          "line_end": 671,
          "support": "Additional simulations at T=10^-6 (O(10^-6) nK) where magnitude of E_c decreases by nearly two orders of magnitude compared to T=1."
        }
      ]
    },
    {
      "condition_id": "temperature_T_one",
      "statement": "Temperature T = 1 (in dimensionless units), corresponding to O(1) nK physically. Used for the high-temperature branch of the E_i scaling and throughout the main text.",
      "anchors": [
        {
          "line_start": 390,
          "line_end": 390,
          "support": "Panel (b) shows E_i at equilibration for various tau_Q at temperature T = 1."
        },
        {
          "line_start": 671,
          "line_end": 671,
          "support": "At simulation temperature T=1 (corresponding to physical temperature O(1) nK) used throughout the main text."
        }
      ]
    }
  ],
  "controls": [
    {
      "name": "tau_Q",
      "definition": "Quench duration, the time over which the chemical potential is linearly ramped from mu_i to mu_f, driving the system through the critical point.",
      "unit": "dimensionless (scaled units)",
      "domain_kind": "continuous_interval",
      "minimum": 100,
      "maximum": 1000,
      "allowed_values": [],
      "domain_statement": "The fitted power laws for E_i are reported for quench times in the interval [100, 1000] for both temperature branches, as confirmed by the reviewer figure evidence.",
      "anchors": [
        {
          "line_start": 443,
          "line_end": 443,
          "support": "Fitted power laws for E_i are given for two temperature values, with the figure showing data for various tau_Q."
        },
        {
          "line_start": 1110,
          "line_end": 1112,
          "support": "Reviewer figure evidence: both fitted curve segments visibly cover the labeled quench-duration interval from tau_Q=10^2 through tau_Q=10^3."
        }
      ]
    }
  ],
  "readouts": [
    {
      "name": "E_i",
      "definition": "Incompressible kinetic energy at equilibration time, defined as E_i = (1/2) integral |u_i(r, t_eq)|^2 d^2r, where u_i is the incompressible (solenoidal) component of the density-weighted velocity field.",
      "unit": "dimensionless (scaled units)",
      "statistic": "Averaged over R=2000 stochastic realizations for T=10^-6 and R=1000 for T=1; error bars denote 1 standard deviation.",
      "uncertainty": "Error bars denote 1 standard deviation; fit uncertainties are reported as plus/minus values with unspecified meaning (source_unspecified).",
      "resolution": null,
      "anchors": [
        {
          "line_start": 394,
          "line_end": 413,
          "support": "Definition of E_i as (1/2) integral |u_i(r, t_eq)|^2 d^2r = integral E_i(k) dk."
        },
        {
          "line_start": 390,
          "line_end": 390,
          "support": "Each data point averaged over R=2000 (T=10^-6) and R=1000 (T=1) stochastic realizations; error bars denote 1 standard deviation."
        }
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "Ei_scaling_T_low",
      "statement": "At temperature T=10^-6, the incompressible kinetic energy at equilibration time scales with quench duration as E_i = (19.774 +/- 5.010) x 10^4 * tau_Q^{-0.971 +/- 0.052}, consistent with the predicted tau_Q^{-1} scaling.",
      "quantitative_form": "E_i = (19.774e4) * tau_Q^(-0.971)",
      "oracle_outputs": {
